export const renderManual = () => `<div class="manual-page">
  ${renderPublicNav('manual')}
  <header class="manual-hero"><div class="manual-hero-grid"><div><p class="manual-eyebrow">SmartCareOps · User Manual</p><h1 id="page-heading" tabindex="-1">A clear path through connected care.</h1><p class="manual-tagline">AI that doesn’t just assess. It coordinates care.</p><p class="manual-hero-copy">A practical guide for patients, doctors, dispatchers, command-center operators, and anyone seeing SmartCareOps for the first time.</p></div><div class="manual-hero-card"><span>CONNECTED CARE AND OPERATIONS</span><strong>From first contact to the right care</strong><small>Patient intake · clinical review · response coordination · network intelligence. Human decision authority throughout.</small></div></div></header>
  <div class="manual-mobile-picker"><span>Jump to a section</span><div>${sectionLinks}</div></div>
  <div class="manual-layout"><aside class="manual-sidebar" aria-label="User Manual sections"><div class="manual-sidebar-title">On this page</div><nav>${sectionLinks}</nav><a class="manual-top-link" href="#overview">Back to overview ↑</a></aside><main class="manual-content">
    ${renderSection('overview', 'Overview', 0, { title: 'What is SmartCareOps?', intro: 'SmartCareOps is an AI-native healthcare intake and coordination platform that connects patients, clinicians, responders, hospitals, and system-wide intelligence—from first contact to the right care.', body: `<div class="manual-operator-section" data-manual-platform-purpose><h3>Why SmartCareOps exists</h3><p>Patients need a clear way to explain their concern and understand what happens next. Clinicians and responders need reliable case information and coordinated actions. Operators need visibility of demand, hospital pressure and available resources across the network. SmartCareOps brings these needs into one connected platform.</p><h3>Three connected capabilities</h3><ul><li><strong>Patient care:</strong> voice or chat intake, Patient-shared evidence, specialty routing, Doctor review and optional appointment follow-up.</li><li><strong>Response coordination:</strong> emergency escalation, Dispatcher decisions, simulated hospital acceptance and fictional ambulance response progress.</li><li><strong>Network intelligence:</strong> hospital pressure, emerging patterns, demand forecasts and CareTwin comparisons to help authorized operators plan.</li></ul><h3>What makes it different?</h3><p>SmartCareOps brings Patient intake, clinical decision support, response coordination and network planning into one connected platform—with preserved Patient evidence, explicit human authority, recorded outcomes and simulated comparisons of response options before action.</p><ul><li><strong>Evidence stays attributable:</strong> Patient-reported facts, descriptions and images remain distinct from AI interpretation and clinical findings.</li><li><strong>Coordination follows the outcome:</strong> case review, appointment confirmation, response acknowledgement and transport progress are saved steps that the appropriate roles can follow.</li><li><strong>Decisions remain accountable:</strong> Doctors own clinical decisions, Dispatchers control response steps, and authorized Command Center operators review network plans. Required approvals must still be current.</li><li><strong>Planning considers the wider network:</strong> aggregate response activity, forecasts and CareTwin comparisons help operators examine simulated alternatives and trade-offs before action.</li></ul><p>These describe the platform’s focus and demonstrated capabilities, not a claim that no other healthcare solution offers similar features. Hospital, ambulance and network operations in this demonstration are fictional or simulated; they do not establish real service availability, admission or dispatch.</p></div><div class="manual-operator-section"><h3>How a Patient case proceeds</h3><p>Patients choose voice or chat. The next path depends on the reported facts; not all cases go to a hospital.</p></div><div class="manual-two-col" data-manual-care-paths><article class="manual-operator-section"><h3>Normal care</h3><p>Patient intake → routed Doctor review → recorded review outcome.</p><p>After approval, the Doctor may offer a fictional appointment for the Patient to confirm. An appointment is optional; approval alone does not book a visit.</p></article><article class="manual-operator-section"><h3>Emergency response</h3><p>Emergency trigger → Dispatcher acknowledgement → simulated hospital acceptance → fictional ambulance response.</p><p>Normal Doctor routing is skipped. Each response action must be explicitly recorded by an authorized Dispatcher.</p></article></div><p>Command Center monitors aggregate response activity and separate fictional network signals. It is not a required final stop for every Patient case.</p>${callout('The important boundary', 'Patient-reported facts are preserved as evidence. AI can organize and recommend, while authorized humans remain responsible for consequential decisions.', 'trust')}` })}
    ${renderSection('how-it-works', 'How It Works', 1, { title: 'How SmartCareOps works', intro: 'SmartCareOps connects evidence, bounded assistance, and human decisions in a clear operational cycle.', body: `<div class="manual-operator-loop" aria-label="Observe, detect, forecast, compare, approve, monitor, replan"><span>Observe</span><b>→</b><span>Detect</span><b>→</b><span>Forecast</span><b>→</b><span>Compare</span><b>→</b><span>Approve</span><b>→</b><span>Monitor</span><b>→</b><span>Replan</span></div><div class="manual-operator-section" data-manual-agentic><h3>What makes SmartCareOps agentic?</h3><p>SmartCareOps uses bounded agents: software helpers with defined limits. They can review only the evidence their role is allowed to use, use a limited set of tools to investigate, prepare plans, and perform only actions the system permits.</p><p>Important actions wait for an authorized person’s approval where required. Before a permitted action proceeds, SmartCareOps checks that the evidence and approval are still current. Expired or superseded approvals cannot be used, repeated requests do not create duplicate actions, and the outcome is recorded.</p><h3>Example: responding to simulated hospital pressure</h3><ol><li>SmartCareOps observes synthetic hospital-capacity pressure.</li><li>It checks the available simulated resource information.</li><li>It prepares a response for comparison and review.</li><li>An authorized operator approves the response when approval is required.</li><li>The permitted simulated outcome is recorded.</li><li>If the evidence changes, the system can re-evaluate the options and prepare a revised plan.</li></ol><p>This demonstration does not contact real hospitals or change real beds, staffing, ambulance assignments, or patient care.</p></div><div class="manual-operator-two" data-manual-ai-boundaries><article class="manual-operator-section"><h3>Conversation</h3><p><strong>Gemini Live</strong> supports the real-time patient intake conversation by listening and responding. It does not independently execute clinical or operational actions.</p></article><article class="manual-operator-section"><h3>Operational intelligence</h3><p><strong>Forecasts, CareTwin comparisons, pattern detection, and simulation</strong> are deterministic or advisory capabilities. They show evidence, projections, and options; they do not independently execute operations.</p></article></div>${callout('Fictional demonstration', 'The hospital conditions, resources, proposed actions, and recorded outcomes shown in this experience are fictional or simulated. They do not imply unrestricted autonomy or real-world hospital contact.', 'trust')}` })}
    ${renderSection('patient', 'Patient', 2, { title: 'Using SmartCareOps as a Patient', intro: 'Start with your own words, follow the conversation, and use the status view to understand what happens next.', body: `<div class="manual-section-actions">${portalLink('/patient', 'Patient Portal')}</div><div class="manual-steps">${patientSteps.map(([n, t, c, next]) => step(n, t, c, next)).join('')}</div>${callout('What you do next', 'Choose a mode → confirm fictional test data → select <strong>Start Conversation</strong> or <strong>Start Chat Intake</strong>. Then follow the saved case status: normal review, optional appointment, or fictional emergency response.', 'patient')}${callout('Typed chat intake', 'Chat intake uses the same one-question-at-a-time clinical intake and case flow without requesting microphone access. Type one answer and press <strong>Enter</strong> to submit; <strong>Shift+Enter</strong> adds a new line. Wait for the next question. If submission fails, keep your answer and retry. Refresh can restore an active chat. During an active chat, you may optionally share one pain-location image with your own description and explicit confirmation. An emergency answer stops routine questions and may show fictional demo hospital information; the demo does not contact a dispatcher, emergency service, or hospital in the real world. The saved emergency case appears in the authorized Dispatcher queue. Use <strong>Cancel chat</strong> to stop an active chat. Finish or cancel the current intake before choosing the other input option; voice and chat answers are not merged into one session. Completed or emergency chats lead to the saved case.', 'patient')}${callout('Multilingual voice intake', 'Before starting voice intake, choose your <strong>Preferred conversation language</strong>. Gemini is instructed to stay in that language unless you explicitly ask to change it, for example, “Please speak in Tagalog.” Names, accents, medical terms, and answers in another language should not switch its reply language. An ambiguous change request should prompt clarification. If the assistant misunderstands, clarify or repeat yourself. This prompt guardrail reduces language drift but cannot guarantee every response. Fixed safety messages and the final completion sentence keep their required wording. The new guardrail still needs live desktop and physical-phone verification.', 'patient')}<aside class="manual-callout patient" data-manual-multimodal><strong>Multimodal intake</strong><p>Patients can speak or type and optionally share a pain-location image with their own description. Voice intake also supports showing a clearly labeled medication package. The patient reviews and confirms any medication details; packaging is not treated as proof of what the patient takes or as a clinical verification. An image or pointing gesture does not diagnose an injury.</p></aside>${patientMedicineGuide}<div class="manual-operator-section" data-manual-pain-evidence><h3>Sharing a pain-location image</h3><ol><li><strong>Voice:</strong> while connected, select <strong>Pain location</strong> under <strong>What would you like to show?</strong>, choose <strong>Use camera</strong>, allow camera access, and choose <strong>Capture photo</strong>.</li><li>Review the image. The body-area description is optional in voice intake. Check the explicit image-sharing confirmation, then choose <strong>Share image with case</strong>.</li><li>Wait for the saved confirmation. On failure, the capture and description remain available; use <strong>Retry sharing image</strong>. Use <strong>Retake photo</strong> if the image needs changing.</li><li><strong>Chat:</strong> open <strong>Share a pain-location image (optional)</strong>, select a JPEG or WebP image, enter your own body-area description (required for chat), confirm sharing, and choose <strong>Share image with case</strong>. Wait for confirmation.</li></ol><p>The description is your report of where it hurts. Images and gestures are not diagnoses or verified findings. Pain-location mode does not read medicine labels.</p><p>Saved images are private to the owning Patient and authorized Doctor. If an image cannot be loaded, do not assume it was reviewed or that the case was deleted.</p></div>${callout('Voice startup delays', 'The first voice connection can take longer when a service needs to start. Keeping one Live service instance warm resolved the cold-start problem in the tested deployment. The minimum instance count is set to 1, so the service does not need to start from zero for the first connection. This does not remove network or Gemini response delays. Watch the connection and waiting-stage messages; do not assume silence means your answer was accepted. Language guardrails do not fix latency.', 'patient')}${callout('A grounded record', 'If you say “I feel dizzy,” the intake preserves reported dizziness. It must not silently turn your words into a diagnosis such as vertigo. Clinical interpretation belongs in review.', 'trust')}` })}
    ${renderSection('doctor', 'Doctor', 3, { title: 'Review the individual case', intro: 'Doctor Portal turns a submitted intake into a focused, evidence-aware clinical review.', body: `<div class="manual-section-actions">${portalLink('/doctor', 'Doctor Portal')}</div><div class="manual-workflow"><span>Patient Reported</span><b>→</b><span>AI Analysis</span><b>→</b><span>Recommendation</span><b>→</b><span>Doctor Decision</span></div><div class="manual-two-col"><div><h3>What you review</h3><ul><li>Patient-reported facts and denials</li><li>Important findings and missing information</li><li>Risks, uncertainty, and possible explanations</li><li>Why, Why Not, and what would change the recommendation</li></ul></div><div><h3>Separate review and recommendation decisions</h3><p>Use <strong>Approve</strong>, <strong>Reject</strong>, or <strong>Defer</strong> to record the Doctor-owned case review. An approval alone does not arrange a visit or transport.</p><p>Individual recommendation approvals have separate states: <strong>Pending</strong> can be actioned when eligible; <strong>Expired</strong> and <strong>Superseded</strong> cannot be reused. Follow the eligibility and current-evidence message shown for that recommendation.</p>${callout('Human responsibility', 'AI supports review. The authorized doctor owns the final clinical decision.', 'trust')}</div></div>${doctorMedicineGuide}${doctorIdpGuide}<div class="manual-operator-section" data-manual-doctor-controls><h3>Assessment and fictional observations</h3><p>Select <strong>Request assessment</strong> to request AI analysis, and <strong>Refresh clinical plan</strong> to reload the saved plan. Check whether an assessment is current or historical. A failed request can retain a previous plan; retained content is not proof of a new successful assessment, and dependent actions remain gated when required.</p><p>Under <strong>Record fictional observation</strong>, choose <strong>Type</strong>, enter <strong>Value</strong> and <strong>Observed at</strong>, choose <strong>Fictional source</strong>, then select <strong>Append observation</strong>. Add only known fictional observations. They append to the case without replacing Patient-reported facts.</p><h3>Specialties and access</h3><p>Only verified specialties allow access to their routed cases. Use <strong>Request another specialty</strong>, choose an available specialty such as <strong>Family Medicine</strong>, then select <strong>Submit for Admin review</strong>. Each specialty needs independent Admin verification; requesting one does not grant access. Review your verified-specialties indicator.</p><p>Review Patient-shared pain images and descriptions as evidence, not a diagnosis. An unavailable image must not be treated as reviewed evidence.</p></div>` })}
    ${renderSection('dispatcher', 'Dispatcher', 4, { title: 'Coordinate the response', intro: 'Follow each saved emergency-response step in order; every action is a fictional simulation.', body: `<div class="manual-section-actions">${portalLink('/dispatcher', 'Dispatcher Portal')}</div><div class="manual-operator-section" data-manual-dispatch-actions><h3>Find and acknowledge a case</h3><p>The emergency queue is ordered newest first. Match the Patient case ID, open the case, and review its reported emergency facts. Select <strong>Acknowledge emergency case</strong> inside the selected case, or <strong>Acknowledge</strong> in the queue. Wait for <strong>Dispatcher acknowledged</strong>. If acknowledgement cannot be confirmed, refresh or retry and check the saved state before continuing.</p><h3>Destination and ambulance</h3><ol><li>Select an eligible fictional hospital and choose <strong>Record simulated hospital acceptance</strong>.</li><li>Select an available fictional ambulance and choose <strong>Assign ambulance (simulation)</strong>.</li><li>Choose <strong>Dispatch ambulance (simulation)</strong>.</li><li>Choose <strong>Record arrival at pickup</strong>.</li><li>Choose <strong>Start simulated transport</strong>.</li><li>Choose <strong>Record arrival at hospital</strong>.</li><li>Choose <strong>Complete simulated response</strong>.</li></ol><p>Wait for each saved confirmation before the next action. Refresh the selected case to confirm persistence. Completing the response releases the unit and removes the case from the active queue; the Patient retains the saved case.</p></div><p>The Patient can refresh the case or Transport view to follow the recorded destination, assignment and available seeded ETA or distance. Command Center receives aggregate counts without Patient details.</p><p class="manual-note">Only emergency cases use this path. Normal review approval does not send a case to Dispatcher. No real ambulance, live GPS tracking, hospital, dispatcher, or emergency service is contacted.</p>` })}
    ${renderSection('command-center', 'Command Center', 5, { title: 'See the bigger picture', intro: 'Command Center is the system-level operations workspace for monitoring the healthcare network, detecting emerging problems, forecasting pressure, comparing response plans, and coordinating human-approved action.', body: `<div class="manual-section-actions">${portalLink('/command-center', 'Command Center')}</div><div class="manual-operator-section" data-manual-response-activity><h3>Emergency response coordination</h3><p>Use <strong>Refresh response activity</strong> to reload aggregate counts for waiting, acknowledged, destination-accepted, assigned and progressing fictional responses. Review fleet availability and simulated hospital beds and arrivals. This view shows no Patient identity or private case details; it is not live GPS tracking and does not acknowledge, assign or dispatch a case automatically.</p></div><div class="manual-operator-section"><h3>What should I monitor?</h3><div class="manual-monitor-grid"><article><strong>Hospital network</strong><ul><li>ED occupancy</li><li>ICU occupancy</li><li>Capacity and critical thresholds</li></ul></article><article><strong>Ambulances</strong><ul><li>Available and deployed units</li><li>Active assignments</li><li>Transport pressure</li></ul></article><article><strong>Current demand</strong><ul><li>Active and incoming cases</li><li>Demand trend</li><li>Regional concentration</li></ul></article><article><strong>Alerts</strong><ul><li>Emerging patterns</li><li>Severity</li><li>Acknowledged status</li></ul></article><article><strong>Future pressure</strong><ul><li>30 / 60 / 120-minute forecasts</li><li>Predicted bottlenecks</li></ul></article></div></div><div class="manual-operator-section"><h3>Network Overview</h3><p>The main screen is for situational awareness: identify which hospitals are normal, elevated, or critical, where ambulance availability is tightening, where demand is increasing, and which regional alerts need attention first. Open details from the available buttons and panels without leaving the overview.</p><div class="manual-checklist"><span>Normal / elevated / critical hospitals</span><span>Ambulance availability</span><span>Increasing demand</span><span>Regional alerts</span></div><figure class="manual-concept-figure" data-manual-command-concept><img src="${hospitalConceptUrl}" alt="Fictional aerial hospital concept with ambulance movements and a Command Center overlay showing illustrative capacity, demand, and alert indicators." loading="lazy" decoding="async"><figcaption><strong>Fictional concept illustration.</strong> This is not an actual SmartCareOps screen or live hospital feed. The hospital, dashboard, statuses, percentages, timestamps, and ambulance details shown are illustrative.</figcaption></figure></div><div class="manual-operator-two"><article class="manual-operator-section"><h3>Pattern Intelligence</h3><p>Pattern Intelligence looks across multiple cases for possible emerging clusters, such as <strong>Possible Emerging Respiratory Cluster</strong>.</p><ul><li>Review observed cases and baseline.</li><li>Check concentration, affected region, severity, and acknowledgement.</li><li>Acknowledge the alert, continue monitoring, and use it as context for planning.</li></ul><small>Operational signal, not a diagnosis.</small></article><article class="manual-operator-section"><h3>Predictive Intelligence</h3><p>Forecasts project the current network forward across 30, 60, and 120 minutes.</p><ul><li>Review projected demand, ED pressure, ICU pressure, and ambulance pressure.</li><li>Identify likely bottlenecks and which resource becomes constrained first.</li></ul><small>Forecasts are advisory and help operators prepare early.</small></article></div><div class="manual-operator-section"><h3>CareTwin</h3><p>CareTwin compares response plans against the same starting conditions. Plan A keeps the current allocation, Plan B redistributes demand, and Plan C uses more aggressive redistribution or reserve capacity.</p><div class="manual-plan-grid"><div><strong>Compare</strong><span>Hospital load · demand distribution · ambulance availability · projected pressure · trade-offs</span></div><div><strong>Review</strong><span>Recommended plan · Why · Why Not · uncertainty · projected effects</span></div></div><p class="manual-note">CareTwin does not execute a plan automatically. An authorized human decides whether to approve it.</p></div><div class="manual-operator-two"><article class="manual-operator-section"><h3>Supporting Operations</h3><ul><li><strong>Hospital Operations:</strong> hospital-specific pressure and local issues.</li><li><strong>Regional Operations:</strong> broader network coordination.</li><li><strong>Notifications:</strong> operational notices and pending communications.</li></ul><small>These are supporting details, not the primary situational-awareness view.</small></article><article class="manual-operator-section" data-manual-hospital-demo><h3>One-click hospital pressure demo</h3><p>Open <strong>Hospital Operations</strong> and choose <strong>Run demo</strong> once. SmartCareOps prepares a fresh fictional scenario, creates hospital capacity pressure, generates the current operational assessment, and waits for the result.</p><p>When it finishes, <strong>What the demo did</strong> summarizes the capacity change and assessment. <strong>CONSTRAINED</strong> means the fictional hospital has limited capacity in the simulated scenario. The two actions awaiting review are <strong>Capacity response simulation</strong> and <strong>Staffing response simulation</strong>. Select the review count in <strong>Current assessment</strong> to open and focus these action cards. The review window lasts 10 minutes; if it expires, choose <strong>Run demo again</strong> to create a current assessment.</p><p class="manual-note">The demo does not contact or reserve a real hospital, bed, staff member, or ambulance. High-impact suggested actions remain under human control.</p></article></div><div class="manual-operator-two"><article class="manual-operator-section"><h3>What can I do?</h3><ul><li>Monitor hospital and ambulance state.</li><li>Review alerts, forecasts, and CareTwin plans.</li><li>Identify bottlenecks and review Why / Why Not.</li><li>Acknowledge alerts and approve authorized actions.</li><li>Monitor results and replan when conditions change.</li></ul></article><article class="manual-operator-section"><h3>When should I act?</h3><ul><li><strong>Pressure rising:</strong> review Predictive Intelligence.</li><li><strong>Emerging cluster:</strong> review concentration and severity in Pattern Intelligence.</li><li><strong>Future bottleneck:</strong> compare plans in CareTwin.</li><li><strong>Consequential action:</strong> complete the human approval step.</li><li><strong>Conditions change:</strong> monitor and re-evaluate.</li></ul></article></div><div class="manual-operator-section"><h3>Command Center demo walkthrough</h3><ol class="manual-walkthrough"><li>Sign in with a Command Center demo account.</li><li>Review <strong>What needs attention</strong>, then open <strong>Hospital Operations</strong>.</li><li>Choose <strong>Run demo</strong> once. No reset, capacity, or assessment button is needed for the judge-facing flow.</li><li>Wait while SmartCareOps prepares the scenario and operational assessment.</li><li>Review <strong>What the demo did</strong>. A <strong>CONSTRAINED</strong> assessment shows that the fictional hospital is under capacity pressure.</li><li>Review the capacity and staffing simulations awaiting human review. The demo does not approve them automatically.</li><li>Open <strong>View hospital details and controls</strong> only when you want supporting evidence, history, or manual demo controls.</li></ol></div>` })}
    ${renderSection('notifications', 'Notifications', 6, { title: 'Notifications across Patient and staff portals', intro: 'Stay informed without losing the full history or the human responsibilities attached to each notice.', body: notificationsGuide })}
    ${renderSection('care-journey', 'Care Journey', 7, { title: 'Your journey follows your case', intro: 'Patient Portal starts with six milestones. Their final labels and active step change with the saved case outcome.', body: `<div class="manual-journey-list">${journey.map(([title, copy, owner], i) => `<article><span>${String(i + 1).padStart(2, '0')}</span><div><h3>${title}</h3><p>${copy}</p><small>${owner}</small></div></article>`).join('')}</div><p>For a completed normal review, the final labels may be <strong>Doctor Decision</strong> and <strong>Review Complete</strong>. An appointment proposal changes them to appointment steps such as <strong>Appointment Proposed</strong> and <strong>Confirm Appointment</strong>. A fictional emergency response uses <strong>Transport</strong> and <strong>Hospital</strong>, then <strong>Response Complete</strong> and <strong>Follow-up</strong>. Emergency cases skip normal clinical review; inactive milestones are not a promise of future hospital care.</p>` })}
    ${renderSection('human-approval', 'Human Approval', 8, { title: 'AI supports action. People approve it.', intro: 'SmartCareOps is designed to keep consequential clinical and operational decisions with authorized humans.', body: `<div class="manual-approval-grid"><article><span>AI CAN</span><ul><li>Analyze and organize evidence</li><li>Recommend and compare options</li><li>Simulate possible outcomes</li><li>Surface risks and uncertainty</li></ul></article><article class="manual-approval-human"><span>HUMANS APPROVE</span><ul><li>Doctors approve clinical decisions</li><li>Dispatchers approve operational response</li><li>Command-center operators approve system plans</li></ul></article></div><p class="manual-note">SmartCareOps presents recommendations with supporting evidence, uncertainty, and trade-offs. It does not replace clinical judgment.</p>` })}
    ${renderSection('technology', 'Technology', 9, { title: 'The foundation behind the journey', intro: 'These technologies support the experience without changing who remains responsible for care.', body: `<div class="manual-section-actions">${portalLink('/technology', 'Technology')}</div><div class="manual-operator-section" data-manual-architecture><h3>Architecture</h3><a href="/images/technology/smartcareops-manual-architecture.png" target="_blank" rel="noopener noreferrer" aria-label="Open SmartCareOps architecture diagram at full size"><img src="/images/technology/smartcareops-manual-architecture.png" alt="SmartCareOps architecture: client portals connect through API Gateway to Cloud Run application services, Gemini AI models, the Clinical Review Agent, and Google Cloud data and security services." loading="lazy" style="display:block;width:100%;height:auto"></a><p><a href="/images/technology/smartcareops-manual-architecture.png" target="_blank" rel="noopener noreferrer">Open architecture diagram at full size</a></p></div><div class="manual-tech-grid" data-manual-technology><article><strong>Gemini Live API</strong><span><code>gemini-3.8-live</code> powers the Patient’s real-time voice intake.</span></article><article><strong>Gemini API</strong><span><code>gemini-3.6-flash</code> supports intake extraction, IDP, and structured analysis. <code>gemini-3.8-flash</code> supports the bounded browser handoff.</span></article><article><strong>SmartCareOps IDP</strong><span>Doctors upload laboratory reports, compare every Gemini-extracted value with the original, correct errors, and verify the results before requesting a review-only assessment.</span></article><article><strong>Managed Clinical Review Agent</strong><span>Gemini Enterprise Agent Platform runs a grounded Clinical Review Agent with <code>gemini-3.6-flash</code> for named fictional demo cases during a bounded demo window. The Doctor Portal identifies the assessment source, and the existing clinical model is the automatic fallback.</span></article><article><strong>Grounding and inspection</strong><span>Vertex AI RAG Engine holds the approved fictional policy corpus used by the managed agent. Model Armor inspected policy admission and remains inspect-only. SmartCareOps validates evidence, schema, current revisions, and permitted tools before displaying an assessment.</span></article><article><strong>Google Cloud platform</strong><span>Firebase, Cloud Run, Firestore, Pub/Sub, Cloud Storage, API Gateway, Identity and Access Management, Secret Manager, and Artifact Registry support the application.</span></article></div>${callout('Fast typed intake', 'Typed intake uses defined questions and safety rules, with common answers handled directly. Gemini helps interpret open-text answers when needed; those answers may take longer. Patient-reported evidence stays separate from later clinical interpretation.', 'trust')}${callout('Separate AI roles', 'Gemini Live handles the voice conversation. Gemini API supports structured extraction and analysis. For named fictional demo cases, Gemini Enterprise Agent Platform can provide the Doctor-visible clinical assessment; the existing clinical model remains the automatic fallback. AI supports the care workflow, while the authorized Doctor remains responsible for the final clinical decision.', 'trust')}` })}
    ${renderSection('security', 'Security & Trust', 10, { title: 'Designed for clear responsibility', intro: 'Trust is part of the product experience.', body: `<div class="manual-trust-list"><article><strong>Identity</strong><span>Google sign-in or a fixed demo account verifies who is using the workspace.</span></article><article><strong>Authorization</strong><span>SmartCareOps keeps patient and staff permissions separate.</span></article><article><strong>Evidence</strong><span>Patient-reported information remains distinct from AI interpretation.</span></article><article><strong>Secrets</strong><span>AI service credentials remain protected and are not shown to portal users.</span></article><article><strong>Regional deployment</strong><span>Application services can be placed near the care network. When a customer has a verified data-residency requirement, applicable services use supported regional endpoints and location policies.</span></article><article><strong>Scope</strong><span>SmartCareOps is decision support and coordination, not autonomous medical care.</span></article></div>` })}
    ${renderSection('demo', 'Demo Guide', 11, { title: 'See SmartCareOps end to end', intro: 'Use fictional details and separate signed-in role sessions for these two walkthroughs.', body: `<div class="manual-two-col"><article class="manual-operator-section"><h3>Emergency trigger</h3><ol><li>Choose chat, confirm fictional test data, then start chat intake.</li><li>Give a fictional name, then report: “I need emergency help. I cannot breathe.” Answer any severity clarification accurately.</li><li>Read the urgent warning and available simulated hospital information. Open My Cases and record the emergency case ID.</li><li>Dispatcher opens that case, acknowledges it, records simulated hospital acceptance and assigns a fictional unit.</li><li>Record dispatch, arrival at pickup, transport, hospital arrival and completion in order.</li><li>Patient refreshes to follow the saved state; Command Center refreshes aggregate response activity.</li></ol></article><article class="manual-operator-section"><h3>Shoulder pain and image</h3><ol><li>Choose voice, confirm fictional data, then start the conversation.</li><li>Report fictional shoulder pain after lifting luggage, its onset and effects. Do not add emergency symptoms to this normal-care scenario.</li><li>While connected, choose Pain location, capture a still, review it, confirm sharing and save the image with the case.</li><li>Complete intake and open My Cases. Verify the reported facts and private evidence.</li><li>A verified Orthopedics Doctor reviews the routed case when available; verified Family Medicine is the fallback, otherwise it remains unassigned.</li><li>Doctor records the review outcome and optionally sends fictional appointment times after approval. Patient confirms one or requests another time.</li></ol></article></div><div class="manual-operator-section" data-manual-demo-console><h3>Verify a case in Demo Console</h3><ol><li>Open the access-controlled Demo Console, paste the fictional Case ID, and choose <strong>Verify trace</strong>.</li><li>For a routine case, check the intake event, audit receipt, Operations projection, and normal routing decision. Hospital Operations activation should read <strong>Not requested</strong>.</li><li>For an emergency case, check the human-controlled Dispatcher pathway and recorded response status. This does not itself start a Hospital Operations session.</li><li>Review <strong>Recent agentic sessions</strong> separately. A fictional hospital-capacity event can start a bounded Operations session; routine Patient intake alone does not.</li></ol><div class="manual-section-actions">${portalLink('/demo-console', 'Demo Console')}</div></div><p class="manual-note">These are demonstrations, not real emergency assistance, diagnosis, admission or booking. The full test walkthroughs are maintained in the project scenario guide.</p><div class="manual-section-actions">${portalLink('/patient', 'Patient Portal')}${portalLink('/doctor', 'Doctor Portal')}${portalLink('/dispatcher', 'Dispatcher Portal')}${portalLink('/command-center', 'Command Center')}</div>` })}
    ${renderSection('admin', 'Admin', 12, { title: 'Manage access and fictional test data', intro: 'Only an authorized Admin can use these controls.', body: `<div class="manual-section-actions">${portalLink('/admin', 'Admin Portal')}</div><div class="manual-operator-section" data-manual-admin><h3>Applications and verified specialties</h3><p>Review Doctor and Patient applications and the Approved Doctors directory. Doctor professional credentials and each requested specialty require their own verification. Approval of one specialty does not approve all specialties. To revoke a specialty, select <strong>Remove</strong> beside it in the Approved Doctors directory and confirm the change. Removing the final verified specialty also removes that account’s Doctor Portal access.</p><h3>Patient Portal access</h3><p>Choose <strong>Anyone signed in</strong> or <strong>Approved patients only</strong>, then select <strong>Save access setting</strong>. Approved-only mode requires Patient application approval before intake. Configured administrators retain Patient access for testing.</p></div>` })}
  </main></div>
</div>`;

export function mountManual(root) {
  const disposeNav = mountPublicNav(root);
  const links = [...root.querySelectorAll('[data-manual-nav]')];
  const targets = sections.map(([id]) => root.querySelector(`#${id}`)).filter(Boolean);
  const observer = new IntersectionObserver((entries) => { const visible = entries.filter(entry => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]; if (!visible) return; links.forEach(link => link.setAttribute('aria-current', link.dataset.manualNav === visible.target.id ? 'location' : 'false')); }, { rootMargin: '-20% 0px -65% 0px', threshold: [0, .25, .6] });
  targets.forEach(target => observer.observe(target));
  return () => { observer.disconnect(); disposeNav(); };
}
